package com.mavric.health.persistence.sqlserver;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.security.core.context.SecurityContextHolder;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.shared.ApiException;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real REQUIRED templates and modeled executor/manager; no real ownership or SQL Server checks. */
class SqlServerSupportStoreTest {
 static final String ID="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",OTHER="cc000000-0000-4000-8000-000000000001",TIME="2026-11-04T00:00:00.123456Z",BODY="\u00c1\u4e2d\ud83e\uddb7".repeat(3000);
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final SqlServerSupportStore store=new SqlServerSupportStore(executor,manager);final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/support");final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();final List<SqlServerProcedure> calls=new ArrayList<>();final List<List<Object>> args=new ArrayList<>();
 SqlServerSupportStoreTest(){authority("PRO",true);when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var context=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,context.scope());assertEquals(ID,context.actorId());assertEquals("a".repeat(64),context.tokenHash());calls.add(inv.getArgument(0));args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));return results.removeFirst();});}
 void authority(String role,boolean tenant){request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",tenant?TENANT:null,List.of(role),"a".repeat(64)));if(tenant)request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));else request.removeAttribute("health.tenant");}
 static Map<String,Object> ticket(String tenant,String actor){var r=new LinkedHashMap<String,Object>();r.put("id",ID);r.put("tenantId",tenant);r.put("actorId",actor);r.put("reference","MVT-SYNTHETIC");r.put("email","qa@example.test");r.put("subject","Synthetic");r.put("message",BODY);r.put("status","OPEN");r.put("priority","NORMAL");r.put("revision",1);r.put("createdAt",TIME);r.put("updatedAt",TIME);return r;}
 static Map<String,Object> comment(){return Map.of("id",OTHER,"message",BODY,"createdAt",TIME,"actorName","Synthetic","tokenHash","private");}
 void rows(List<Map<String,Object>> rows){results.add(new SqlServerExecutor.Result(List.of(rows),List.of(0)));}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable work){var e=assertThrows(ApiException.class,work::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());}
 @Test void exactTwoDescriptorsLongUnicodeProjectionsImmutableAndPlatformNullable(){var row=ticket(TENANT,ID);row.put("passwordHash","private");rows(List.of(row));var listed=store.list(request);assertEquals(12,listed.getFirst().size());assertEquals(BODY,listed.getFirst().get("message"));assertThrows(UnsupportedOperationException.class,listed::clear);assertThrows(UnsupportedOperationException.class,listed.getFirst()::clear);results.add(new SqlServerExecutor.Result(List.of(List.of(row),List.of(comment())),List.of()));var detail=store.detail(request,ID);var comments=(List<Map<String,Object>>)detail.get("comments");assertEquals(13,detail.size());assertEquals(4,comments.getFirst().size());assertEquals(BODY,comments.getFirst().get("message"));assertThrows(UnsupportedOperationException.class,comments::clear);assertThrows(UnsupportedOperationException.class,comments.getFirst()::clear);assertEquals(List.of(SqlServerProcedure.SUPPORT_LIST,SqlServerProcedure.SUPPORT_DETAIL),calls);assertEquals(List.of(),args.getFirst());assertEquals(List.of(ID),args.getLast());authority("SOP",false);rows(List.of(ticket(null,null)));var nullable=store.list(request).getFirst();assertTrue(nullable.containsKey("tenantId"));assertNull(nullable.get("tenantId"));assertNull(nullable.get("actorId"));}
 @Test void listLimitsAndEmptyPerHost(){for(boolean platform:List.of(false,true)){authority(platform?"SAD":"PAC",!platform);int max=platform?200:100;rows(List.of());assertEquals(List.of(),store.list(request));var input=new ArrayList<Map<String,Object>>();for(int i=0;i<max;i++)input.add(ticket(platform?null:TENANT,platform?null:ID));rows(input);assertEquals(max,store.list(request).size());input.add(input.getFirst());rows(input);safe(()->store.list(request));}}
 @Test void detailAllCommentsArePreservedWithoutArbitraryLimitAndMissing404(){var comments=new ArrayList<Map<String,Object>>();for(int i=0;i<500;i++)comments.add(comment());results.add(new SqlServerExecutor.Result(List.of(List.of(ticket(TENANT,ID)),comments),List.of()));assertEquals(500,((List<?>)store.detail(request,ID).get("comments")).size());results.add(new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()));assertEquals(404,assertThrows(ApiException.class,()->store.detail(request,ID)).status);}
 @Test void everyTicketColumnRequiredAndMalformedEnumsRevisionTimesIdsRollback(){for(String key:ticket(TENANT,ID).keySet()){var row=ticket(TENANT,ID);row.remove(key);rows(List.of(row));safe(()->store.list(request));}for(var replacement:List.of(Map.entry("id","bad"),Map.entry("revision",1L),Map.entry("revision",0),Map.entry("status","open"),Map.entry("priority","bad"),Map.entry("message",1),Map.entry("createdAt","2026-11-04T00:00:00.123456789Z"),Map.entry("updatedAt","2026-11-04T00:00:00+00:00"))){var row=ticket(TENANT,ID);row.put(replacement.getKey(),replacement.getValue());rows(List.of(row));safe(()->store.list(request));assertEquals("rollback",manager.events.getLast());}}
 @Test void foreignTenantOrAuthorNeverFilteredSilentlyAndWrongDetailIdFails(){for(var row:List.of(ticket(OTHER,ID),ticket(TENANT,OTHER),ticket(null,null))){rows(List.of(row));safe(()->store.list(request));}var wrong=ticket(TENANT,ID);wrong.put("id",OTHER);results.add(new SqlServerExecutor.Result(List.of(List.of(wrong),List.of()),List.of()));safe(()->store.detail(request,ID));}
 @Test void resultsetsDetailCardinalityAndMalformedCommentFailClosed(){for(var sets:List.<List<List<Map<String,Object>>>>of(List.of(),List.of(List.of()),List.of(List.of(ticket(TENANT,ID),ticket(TENANT,ID)),List.of()))){results.add(new SqlServerExecutor.Result(sets,List.of()));safe(()->store.detail(request,ID));}var bad=new LinkedHashMap<>(comment());bad.put("actorName",null);results.add(new SqlServerExecutor.Result(List.of(List.of(ticket(TENANT,ID)),List.of(bad)),List.of()));safe(()->store.detail(request,ID));}
 @Test void directContextAndBadIdGuardsBeforeExecutor(){assertEquals(400,assertThrows(ApiException.class,()->store.detail(request,"bad")).status);request.removeAttribute("health.actor");assertEquals(403,assertThrows(ApiException.class,()->store.list(request)).status);authority("PRO",false);assertEquals(403,assertThrows(ApiException.class,()->store.list(request)).status);authority("PRO",true);request.setAttribute("health.tenant","forged");safe(()->store.list(request));safe(()->store.list(null));verifyNoInteractions(executor);}
 @Test void requiredJoinCommitAndVendor404NoRetry(){rows(List.of(ticket(TENANT,ID)));assertThrows(RuntimeException.class,()->manager.outer(()->{store.list(request);assertEquals(List.of("begin:0"),manager.events);throw new RuntimeException("synthetic cancel");}));assertEquals("rollback",manager.events.getLast());rows(List.of(ticket(TENANT,ID)));manager.failCommit=true;safe(()->store.list(request));doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,51002))).when(executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->store.detail(request,ID));assertEquals(404,e.status);assertFalse(e.toString().contains("private"));verify(executor,times(3)).execute(any(),any(),any(Object[].class));}
 @Test void directAuthorityMismatchAndMalformedUuidHashNeverExecutor(){request.setAttribute("health.tenant",new TenantRef(OTHER,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));assertEquals(403,assertThrows(ApiException.class,()->store.list(request)).status);authority("PRO",true);request.setAttribute("health.actor",new Actor("bad","Synthetic","qa@example.test",TENANT,List.of("PRO"),"a".repeat(64)));safe(()->store.list(request));request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",TENANT,List.of("PRO"),"bad"));safe(()->store.list(request));verifyNoInteractions(executor);}
 @Test void eachCommentColumnRequiredAndUtcPrecisionValidatedInsideTransaction(){for(String key:List.of("id","message","createdAt","actorName")){var bad=new LinkedHashMap<>(comment());bad.remove(key);results.add(new SqlServerExecutor.Result(List.of(List.of(ticket(TENANT,ID)),List.of(bad)),List.of()));safe(()->store.detail(request,ID));assertEquals("rollback",manager.events.getLast());}var bad=new LinkedHashMap<>(comment());bad.put("createdAt","2026-11-04T00:00:00.123456789Z");results.add(new SqlServerExecutor.Result(List.of(List.of(ticket(TENANT,ID)),List.of(bad)),List.of()));safe(()->store.detail(request,ID));}

}
